const renderConsumptionTypes=()=>{const typeOptions=[['planned','계획 소비'],['unplanned','비계획 소비'],['unknown','미분류']];const chosen=(classificationPeriod==='month'?monthExpenses:periodExpenses).filter(e=>(e.consumptionType||'unknown')===expenseTypeFilter);return <section className="card consumption-types"><h2>소비 유형별 내역</h2><div className="plan-inner-tabs">{typeOptions.map(([v,t])=><button key={v} className={expenseTypeFilter===v?'selected':''} onClick={()=>setExpenseTypeFilter(v)}>{t}</button>)}</div><div className="spread"><small>{classificationPeriod==='month'?month+' 기준':'상단 분석 기간 기준'} · {chosen.length}건</small><strong>{won(chosen.reduce((a,e)=>a+Number(e.amount||0),0))}</strong></div>{chosen.sort((a,b)=>b.date.localeCompare(a.date)).map(e=><div key={e.id} className="consumption-row"><div><b>{e.memo||e.subcategory||e.category}</b><small>{e.date} · {e.category}{e.subcategory?' · '+e.subcategory:''}</small></div><div className="consumption-actions"><strong>{won(e.amount)}</strong>{!e.planId&&<select aria-label="소비 유형 분류" value={e.consumptionType||'unknown'} onChange={ev=>classifyExpense(e.id,ev.target.value)}><option value="unknown">미분류</option><option value="planned">계획 소비 (직접 확인)</option><option value="unplanned">비계획 소비</option></select>}</div></div>)}{!chosen.length&&<p className="muted small">이 유형의 지출 기록이 없어.</p>}<p className="muted small">일반 + 입력은 미분류야. 계획 구매에서 등록한 지출은 자동으로 계획 소비가 돼.</p></section>};
const renderBudget=()=> <div className="page"><div className="topline"><div><h1>예산</h1><p>이번 달의 소비를 계획해요</p></div><div className="budget-top-actions"><button className="iconbtn kpi-launch" aria-label="KPI 관리 열기" title="KPI 관리" onClick={()=>setShowKPI(true)}><Target size={19}/></button><button className="iconbtn" aria-label="데이터 관리" onClick={()=>setShowSettings(true)}><Settings2 size={19}/></button></div></div><MonthSelector month={month} change={changeMonth}/><section className="card hero"><div className="eyebrow">이번 달 남은 예산</div><div className={'mega '+(remaining<0?'bad':'')}>{won(remaining)}</div><div className="progress"><div style={{width:`${Math.min(100,monthTotal/(Number(activeBudget)||1)*100)}%`}}/></div><div className="spread caption"><span>지출 {won(monthTotal)}</span><span>예산 {won(activeBudget)}</span></div><div className="budget-controls"><label className="field">월 전체 예산<input inputMode="numeric" type="number" placeholder="예산 입력" value={activeBudget} onChange={e=>saveMonthlyBudget(e.target.value)} onFocus={e=>e.target.select()}/></label><button type="button" className="secondary copy-budget" onClick={copyPreviousBudget}><Repeat size={15}/> 지난달 예산 복사</button></div></section><div className="duo"><div className="card stat"><small>하루 사용 가능액</small><strong>{won(Math.max(0,remaining)/daysLeft)}</strong><span>남은 {daysLeft}일 기준</span></div><div className="card stat"><small>등록된 월 고정비</small><strong>{won(monthFixed)}</strong><span>결제 일정은 고정비 탭에서</span></div></div><div className="spread section-heading budget-heading"><h2>카테고리별 예산</h2><div className="budget-heading-actions"><button type="button" className={"category-budget-add "+(budgetSort==="alpha"?"sort-active":"")} aria-label="카테고리 가나다순 정렬" title="가나다순 정렬" aria-pressed={budgetSort==="alpha"} onClick={()=>setBudgetSort("alpha")}>ㄱ</button><button type="button" className={"category-budget-add "+(budgetSort==="amount"?"sort-active":"")} aria-label="카테고리 지출액 내림차순 정렬" title="지출액 큰 순" aria-pressed={budgetSort==="amount"} onClick={()=>setBudgetSort("amount")}>↓</button><button type="button" className="category-budget-add" aria-label="카테고리별 예산 합계를 월 전체 예산에 반영" title="카테고리 예산 합계를 월 전체 예산에 반영" onClick={applyCategoryBudgetTotal}><Plus size={17}/></button></div></div>{[...names].sort((a,b)=>budgetSort==="alpha"?a.localeCompare(b,"ko"):budgetSort==="amount"?monthCat(b)-monthCat(a)||a.localeCompare(b,"ko"):0).map(c=>{const used=monthCat(c),lim=Number(activeCategoryBudgets[c]||0),isOpen=expandedBudget===c;return <div className="card budget-row" key={c}><button className="budget-trigger" onClick={()=>setExpandedBudget(isOpen?null:c)}><div className="spread"><b>{c}</b><span>{won(used)} {lim?' / '+won(lim):''} {isOpen?<ChevronUp size={15}/>:<ChevronDown size={15}/>}</span></div><div className="progress slim"><div style={{width:`${lim?Math.min(100,used/lim*100):0}%`,background:lim&&used>lim?'#6d568d':undefined}}/></div><div className="spread caption"><span>{lim?`잔액 ${won(lim-used)} / 하루 사용 가능액 ${won(Math.max(0,lim-used)/daysLeft)}`:'예산 미설정'}</span><span>{lim?`${Math.round(used/lim*100)}%`:'선택사항'}</span></div></button>{isOpen&&<div className="nested"><label className="field">{c} 예산<input type="number" value={activeCategoryBudgets[c]??''} placeholder="설정하지 않아도 돼" onChange={e=>saveBudget(c,e.target.value)}/></label><div className="spread expense-heading"><h3>{month.slice(5)}월 지출 내역</h3><button type="button" className="expense-budget-plus" title="이 카테고리의 월 지출 합계를 예산으로 적용" aria-label={`${c} 월 지출 합계를 예산에 반영`} onClick={()=>{const total=monthCat(c);if(total<=0){notify('합산할 지출 내역이 없어.');return;}const previous=Number(activeCategoryBudgets[c]||0);if(previous!==total&&previous>0&&!window.confirm(`${c} 예산을 ${won(previous)}에서 이번 달 지출 합계 ${won(total)}으로 변경할까?`))return;saveBudget(c,String(total));notify(`${c} 예산에 ${won(total)}을 반영했어.`);}}><Plus size={17}/></button></div>{expenseRows(monthExpenses.filter(e=>e.category===c))}</div>}</div>})}</div>;
const renderSchedule=()=> <div className="page"><div className="topline"><div><h1>일정</h1><p>소비·납부 일정을 날짜별로</p></div></div><div className="card"><MonthSelector month={month} change={changeMonth}/>{renderCalendar()}<div className="legend"><span>● 소비 금액</span><span>◆ 고정비 예정</span><span>● 세금 일정</span></div></div><div className="section-heading"><h2>{selectedDate} 기록</h2><small>총 {won(dayRows.reduce((s,e)=>s+Number(e.amount),0))}</small></div><div className="card"><h3>지출 내역</h3>{expenseRows(dayRows)}</div><div className="card"><h3>예정된 고정비</h3>{scheduledFor(selectedDate).length?scheduledFor(selectedDate).map(f=><div className="spread smallrow" key={f.id}><span>{f.name}</span><b>{won(f.amount)}</b></div>):<p className="muted small">이날 예정된 고정비가 없어.</p>}<h3 style={{marginTop:18}}>세금 일정</h3>{store.tax.filter(t=>t.date===selectedDate).length?store.tax.filter(t=>t.date===selectedDate).map(t=><div className="spread smallrow" key={t.id}><span>{t.name} · {t.kind}</span><b>{t.paid?'완료':t.amount?won(t.amount):'금액 미정'}</b></div>):<p className="muted small">등록된 세금 일정이 없어.</p>}</div></div>;
